package com.guardianxr.ar;
import android.app.*;import android.os.*;import android.graphics.Color;import android.content.*;import android.widget.*;
public class AdminActivity extends Activity{@Override protected void attachBaseContext(Context n){super.attachBaseContext(LocaleUtil.apply(n));}public void onCreate(Bundle b){super.onCreate(b);SharedPreferences p=getSharedPreferences("guardianxr",MODE_PRIVATE);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(30,50,30,30);l.setBackgroundColor(0xff07101c);TextView t=new TextView(this);t.setTextColor(Color.WHITE);t.setTextSize(19);String pass=getString(R.string.passed),pending=getString(R.string.pending);t.setText("GuardianXR • "+getString(R.string.admin_dashboard)+"\n\n🔥 "+getString(R.string.fire_assessment)+": "+p.getInt("FIRE_score",0)+"%\n"+getString(R.string.status)+": "+(p.getBoolean("FIRE_passed",false)?pass:pending)+"\n\n☁ "+getString(R.string.gas_assessment)+": "+p.getInt("GAS_score",0)+"%\n"+getString(R.string.status)+": "+(p.getBoolean("GAS_passed",false)?pass:pending)+"\n\n"+getString(R.string.last_certificate)+": "+p.getString("last_cert",getString(R.string.none))+"\n\n● "+getString(R.string.local_records));l.addView(t);setContentView(l);}}
